WITH flattened_attrs AS (SELECT id, plan, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers WHERE plan = 'pro') SELECT *, RANK() OVER w_part AS lowest_price_rank, SUM(lowest_price) OVER (PARTITION BY plan) AS plan_sum_lowest_price, NTILE(4) OVER w_grp AS lowest_price_bucket, LEAD(lowest_price, 2) OVER w_grp AS next_lowest_price FROM flattened_attrs WINDOW w_part AS (ORDER BY lowest_price DESC NULLS FIRST), w_grp AS (PARTITION BY plan ORDER BY lowest_price, id);
